func BuildMessages(system, user string) []Message {
	return []Message{
		{Role: RoleSystem, Content: strings.TrimSpace(system)},
		{Role: RoleUser, Content: strings.TrimSpace(user)},
	}
}

func BuildConversation(history []Message, nextUserMessage string) []Message {
	out := make([]Message, 0, len(history)+1)
	out = append(out, history...)
	out = append(out, Message{Role: RoleUser, Content: strings.TrimSpace(nextUserMessage)})
	return out
}
